247	    @Override
248	    @Transactional
249	    public void saveOwner(Owner owner) throws DataAccessException {
250	        boolean isNew = owner.isNew();
251	        // Resolve the effective registration date (supplied, or defaulted to the server date) and
252	        // roll it forward to the next business day so it never lands on a weekend. Everything
253	        // derived from the registration date below must use this adjusted value.
254	        LocalDate registrationDate = toBusinessDay(
255	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
256	        owner.setRegistrationDate(registrationDate);
257	        if (owner.isNew() && ownerRepository.existsByTelephone(owner.getTelephone())) {
258	            throw new DuplicateTelephoneException(owner.getTelephone());
259	        }
260	        if (owner.isNew()
261	            && countOwnersInCity(owner) >= CityOwnerLimitExceededException.MAX_OWNERS_PER_CITY) {
262	            throw new CityOwnerLimitExceededException(owner.getCity());
263	        }
264	        if (owner.isNew()
265	            && countOwnersRegisteredOn(registrationDate) >= DailyOwnerLimitExceededException.MAX_OWNERS_PER_DAY) {
266	            throw new DailyOwnerLimitExceededException(registrationDate);
267	        }
268	        if (owner.isNew()) {
269	            List<Owner> householdMembers = findHouseholdMembers(owner);
270	            if (!householdMembers.isEmpty()) {
271	                if (!owner.isSharesHousehold()) {
272	                    throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
273	                }
274	                owner.setHouseholdId(resolveHouseholdId(householdMembers));
275	            }
276	            // Size of the household after this create: the existing members plus this new owner.
277	            owner.setHouseholdMemberCount(householdMembers.size() + 1);
278	        }
279	        if (owner.isNew() && owner.getCustomerCode() == null) {
280	            owner.setCustomerCode(generateCustomerCode(owner));
281	        }
282	        if (owner.isNew()) {
283	            owner.setNamesakeCount(countNamesakes(owner));
284	            owner.setBulkSignupWarning(
285	                countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
286	        }
287	        if (owner.getMembershipNumber() == null) {
288	            owner.setMembershipNumber(generateMembershipNumber(owner));
289	        }
290	        ownerRepository.save(owner);
291	        if (isNew) {
292	            AUDIT.info("owner created id={} customerCode={} membershipLevel={} registrationDate={}",
293	                owner.getId(), owner.getCustomerCode(), owner.getMembershipLevel(),
294	                owner.getRegistrationDate());
295	        }
296	    }
297	
298	    /**
299	     * Count the owners that already exist (before this create) sharing the same first name and last
300	     * name as {@code owner}, compared case-insensitively. Returns zero when the owner's name is
301	     * unique among the existing owners.
302	     */
303	    private int countNamesakes(Owner owner) {
304	        String firstName = owner.getFirstName();
305	        String lastName = owner.getLastName();
306	        if (firstName == null || lastName == null) {
307	            return 0;
308	        }
309	        return (int) ownerRepository.findAll().stream()
310	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
311	                && lastName.equalsIgnoreCase(existing.getLastName()))
312	            .count();
313	    }
314	
315	    /**
316	     * Find the owners that already belong to the same household as {@code owner}, i.e. have the same
317	     * last name and the same address. Last names are compared case-insensitively with collapsed
318	     * whitespace; addresses are compared in their canonical normalized form (see
319	     * {@link AddressNormalizer}), so differences in letter case, runs of spaces or street-type
320	     * abbreviations are ignored. Returns an empty list when the owner has no last name or address to
321	     * match on.
322	     */
323	    private List<Owner> findHouseholdMembers(Owner owner) {
324	        String lastName = normalizeHouseholdKey(owner.getLastName());
325	        String address = AddressNormalizer.normalize(owner.getAddress());
326	        if (lastName == null || address == null) {
327	            return List.of();
328	        }
329	        return ownerRepository.findAll().stream()
330	            .filter(existing -> lastName.equals(normalizeHouseholdKey(existing.getLastName()))
331	                && address.equals(AddressNormalizer.normalize(existing.getAddress())))
332	            .toList();
333	    }
334	
335	    /**
336	     * Resolve the stable {@code householdId} shared by a household. If any existing member already
337	     * carries one it is reused so the identifier stays stable as further owners join; otherwise a
338	     * new one is generated. The resolved value is back-filled onto every member that is missing it
339	     * (or has a different one) so all members of the household share the same identifier.
340	     */
341	    private String resolveHouseholdId(List<Owner> members) {
342	        String householdId = members.stream()
343	            .map(Owner::getHouseholdId)
344	            .filter(id -> id != null && !id.isBlank())
345	            .findFirst()
346	            .orElseGet(() -> UUID.randomUUID().toString());
347	        for (Owner member : members) {
348	            if (!householdId.equals(member.getHouseholdId())) {
349	                member.setHouseholdId(householdId);
350	                ownerRepository.save(member);
351	            }
352	        }
353	        return householdId;
354	    }
355	
356	    /**
357	     * Normalize a value for case-insensitive, whitespace-insensitive household comparison by
358	     * trimming, collapsing internal runs of whitespace to a single space and lower-casing it.
359	     */
360	    private String normalizeHouseholdKey(String value) {
361	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase();
362	    }
363	
364	    /**
365	     * Build an owner's {@code customerCode} as {@code '<CITY3>-<LAST3>-<NNNN>'}: CITY3 is the
366	     * upper-cased first three letters of the owner's city, LAST3 the upper-cased first three
367	     * letters of the owner's last name, and NNNN a per-city 4-digit zero-padded sequence equal
368	     * to one more than the number of owners already in that city (e.g. {@code 'LON-SMI-0007'}).
369	     */
370	    private String generateCustomerCode(Owner owner) {
371	        String city3 = upperPrefix3(owner.getCity());
372	        String last3 = upperPrefix3(owner.getLastName());
373	        long sequence = countOwnersInCity(owner) + 1L;
374	        return String.format("%s-%s-%04d", city3, last3, sequence);
375	    }
376	
377	    /**
378	     * Return the upper-cased first three letters of {@code value} (or fewer when it is shorter),
379	     * the shared truncate-and-upper idiom used for each {@code customerCode} prefix segment.
380	     */
381	    private String upperPrefix3(String value) {
382	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
383	    }
384	
385	    /**
386	     * Count the owners that already exist (before this create) in the same city as {@code owner},
387	     * compared case-insensitively.
388	     */
389	    private long countOwnersInCity(Owner owner) {
390	        String city = owner.getCity();
391	        return ownerRepository.findAll().stream()
392	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
393	            .count();
394	    }
395	
396	    /**
397	     * Count the owners that already exist (before this create) whose {@code registrationDate} falls
398	     * on the given {@code date}. Used to enforce the per-day create cap.
399	     */
400	    private long countOwnersRegisteredOn(LocalDate date) {
401	        return ownerRepository.findAll().stream()
402	            .filter(existing -> date.equals(existing.getRegistrationDate()))
403	            .count();
404	    }
405	
406	    /**
407	     * Roll {@code date} forward to the next business day when it falls on a weekend: a Saturday or
408	     * Sunday becomes the following Monday, while a weekday is returned unchanged. Registration dates
409	     * are required to fall on a business day.
410	     */
411	    private LocalDate toBusinessDay(LocalDate date) {
412	        switch (date.getDayOfWeek()) {
413	            case SATURDAY:
414	                return date.plusDays(2);
415	            case SUNDAY:
416	                return date.plusDays(1);
417	            default:
418	                return date;
419	        }
420	    }
421	
422	    /**
423	     * Build an owner's {@code membershipNumber} as {@code '<customerCode>-M<YY>'}, where YY is the
424	     * last two digits of the owner's {@code registrationDate} year (e.g. {@code 'SMI-0007-M26'}).
425	     */
426	    private String generateMembershipNumber(Owner owner) {
427	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
428	        return String.format("%s-M%s", owner.getCustomerCode(), yy);
429	    }
