451	            return supplier.get();
452	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
453	            // Just ignore not found exceptions for Jdbc/Jpa realization
454	            return null;
455	        }
456	    }
457	
458	}
